// build.gradle.kts
abstract class EnvCheckTask : DefaultTask() {
    @get:Input
    abstract val userName: Property<String>

    @TaskAction
    fun run() {
        logger.lifecycle("Hello, ${userName.get()}")
    }
}

tasks.register<EnvCheckTask>("envCheck") {
    // lazy provider, declared as an input — safe to cross the cache boundary
    userName.set(providers.environmentVariable("USER").orElse("unknown"))
}

