import com.android.build.api.variant.SingleArtifact

abstract class MergeSignedHeaderTask : DefaultTask() {
    @get:InputFile
    abstract val inputFile: RegularFileProperty

    @get:OutputFile
    abstract val outputFile: RegularFileProperty

    @TaskAction
    fun merge() {
        outputFile.get().asFile.writeText(inputFile.get().asFile.readText())
    }
}

androidComponents {
    onVariants(selector().all()) { variant ->
        val producer = tasks.register("${variant.name}MergeSignedHeader", MergeSignedHeaderTask::class.java) {
            it.inputFile.set(project.layout.projectDirectory.file("headers/${variant.name}.json"))
        }
        variant.artifacts
            .use(producer)
            .wiredWith(MergeSignedHeaderTask::outputFile)
            .toTransform(SingleArtifact.APK)
    }
}

