package com.example.lint

class NoHardcodedLogTagDetector : Detector(), SourceCodeScanner {
    override fun getApplicableMethodNames(): List<String> = listOf("d", "i", "w", "e")

    override fun visitMethod(context: JavaContext, node: UMethod, method: PsiMethod) {
        if (method.containingClass?.qualifiedName != "android.util.Log") return
        val tag = node.uastArguments.firstOrNull()?.evaluate()?.value as? String ?: return
        if (tag == "TAG") {
            context.report(
                ISSUE, node, context.getLocation(node),
                "Hardcoded log tag; use a single constant",
                LintFix.create().replace().text("TAG").with("LOG_TAG").build()
            )
        }
    }

    companion object {
        val ISSUE = Issue.create(
            "HardcodedLogTag",
            "Hardcoded log tag",
            "Log tags should come from one constant so they are greppable.",
            Category.CORRECTNESS, 5, Severity.WARNING,
            Implementation(NoHardcodedLogTagDetector::class.java, Scope.JAVA_FILE_SCOPE)
        )
    }
}

