class Debouncer(
    private val scope: CoroutineScope,
    private val onFire: () -> Unit,
) {
    private var job: Job? = null

    fun trigger() {
        job?.cancel()
        job = scope.launch {
            delay(300)          // virtual under TestCoroutineScheduler
            onFire()
        }
    }
}

class DebouncerTest {
    @Test
    fun `debounce window is virtual time`() = runTest {
        var fired = false
        val debouncer = Debouncer(this) { fired = true }

        debouncer.trigger()
        testScheduler.advanceTimeBy(299)
        runCurrent()
        assertFalse(fired)

        testScheduler.advanceTimeBy(1)
        runCurrent()
        assertTrue(fired)
    }
}

